CREATE TABLE generated_image_watches(request_id TEXT PRIMARY KEY REFERENCES requests(id),thread_id TEXT NOT NULL,instance_id TEXT NOT NULL,generation TEXT NOT NULL,accepted_generation TEXT,response_id TEXT NOT NULL,conversation_id TEXT NOT NULL,workspace_id TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT -1,digest TEXT,state TEXT NOT NULL DEFAULT 'WATCHING',inventory_state TEXT,snapshot TEXT,terminal_observed_ms INTEGER,deadline_ms INTEGER,next_poll_ms INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,error_code TEXT,UNIQUE(instance_id,generation,response_id,thread_id));
CREATE TABLE generated_image_items(request_id TEXT NOT NULL REFERENCES generated_image_watches(request_id),image_id TEXT NOT NULL,ordinal INTEGER NOT NULL,state TEXT NOT NULL,artifact_id TEXT,delivery_id TEXT REFERENCES resource_deliveries(id),first_seen_ms INTEGER NOT NULL,PRIMARY KEY(request_id,image_id),UNIQUE(request_id,ordinal));
CREATE INDEX image_watch_poll ON generated_image_watches(state,next_poll_ms);
CREATE TABLE artifact_delivery_claims(instance_id TEXT NOT NULL,generation TEXT NOT NULL,artifact_id TEXT NOT NULL,thread_id TEXT NOT NULL,delivery_id TEXT NOT NULL REFERENCES resource_deliveries(id),PRIMARY KEY(instance_id,generation,artifact_id,thread_id));
ALTER TABLE resource_deliveries ADD COLUMN image_request_id TEXT REFERENCES generated_image_watches(request_id);
ALTER TABLE resource_deliveries ADD COLUMN image_ordinal INTEGER;
